const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], q = tok[1];
const a = tok.slice(2, 2 + n);
const par = [0, 0].concat(tok.slice(2 + n, 1 + 2 * n));
const size = new Array(n + 1).fill(1);
for (let v = n; v >= 2; v--) size[par[v]] += size[v];
const tin = new Array(n + 1).fill(0), nxt = new Array(n + 1).fill(0);
tin[1] = 1; nxt[1] = 2;
for (let v = 2; v <= n; v++) {
  const p = par[v];
  tin[v] = nxt[p];
  nxt[p] += size[v];
  nxt[v] = tin[v] + 1;
}
const bit = new Array(n + 2).fill(0);
const add = (i, d) => { for (; i <= n; i += i & -i) bit[i] += d; };
const prefix = (i) => { let s = 0; for (; i > 0; i -= i & -i) s += bit[i]; return s; };
for (let v = 1; v <= n; v++) add(tin[v], a[v - 1]);
const out = [];
let pos = 2 * n + 1;
for (let i = 0; i < q; i++) {
  const k = tok[pos];
  if (k === 1) {
    const v = tok[pos + 1], x = tok[pos + 2];
    add(tin[v], x - a[v - 1]);
    a[v - 1] = x;
    pos += 3;
  } else {
    const v = tok[pos + 1];
    out.push(prefix(tin[v] + size[v] - 1) - prefix(tin[v] - 1));
    pos += 2;
  }
}
console.log(out.join("\n"));

