import java.util.*;

public class Main {
    static long[] bit;
    static int n;

    static void add(int i, long d) { for (; i <= n; i += i & -i) bit[i] += d; }

    static long prefix(int i) { long s = 0; for (; i > 0; i -= i & -i) s += bit[i]; return s; }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        int q = sc.nextInt();
        long[] a = new long[n + 1];
        for (int i = 1; i <= n; i++) a[i] = sc.nextLong();
        int[] par = new int[n + 1];
        for (int v = 2; v <= n; v++) par[v] = sc.nextInt();
        int[] size = new int[n + 1];
        Arrays.fill(size, 1);
        for (int v = n; v >= 2; v--) size[par[v]] += size[v];
        int[] tin = new int[n + 1], nxt = new int[n + 1];
        tin[1] = 1;
        nxt[1] = 2;
        for (int v = 2; v <= n; v++) {
            int p = par[v];
            tin[v] = nxt[p];
            nxt[p] += size[v];
            nxt[v] = tin[v] + 1;
        }
        bit = new long[n + 2];
        for (int v = 1; v <= n; v++) add(tin[v], a[v]);
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            int k = sc.nextInt();
            if (k == 1) {
                int v = sc.nextInt();
                long x = sc.nextLong();
                add(tin[v], x - a[v]);
                a[v] = x;
            } else {
                int v = sc.nextInt();
                out.append(prefix(tin[v] + size[v] - 1) - prefix(tin[v] - 1)).append('\n');
            }
        }
        System.out.print(out);
    }
}

