#include <bits/stdc++.h>
using namespace std;
int n;
vector<long long> bit;
void add(int i, long long d) { for (; i <= n; i += i & -i) bit[i] += d; }
long long prefix(int i) { long long s = 0; for (; i > 0; i -= i & -i) s += bit[i]; return s; }
int main() {
    int q;
    scanf("%d %d", &n, &q);
    vector<long long> a(n + 1);
    for (int i = 1; i <= n; i++) scanf("%lld", &a[i]);
    vector<int> par(n + 1, 0), size(n + 1, 1), tin(n + 1, 0), nxt(n + 1, 0);
    for (int v = 2; v <= n; v++) scanf("%d", &par[v]);
    for (int v = n; v >= 2; v--) size[par[v]] += size[v];
    tin[1] = 1;
    nxt[1] = 2;
    for (int v = 2; v <= n; v++) {
        int p = par[v];
        tin[v] = nxt[p];
        nxt[p] += size[v];
        nxt[v] = tin[v] + 1;
    }
    bit.assign(n + 2, 0);
    for (int v = 1; v <= n; v++) add(tin[v], a[v]);
    while (q--) {
        int k, v;
        scanf("%d %d", &k, &v);
        if (k == 1) {
            long long x;
            scanf("%lld", &x);
            add(tin[v], x - a[v]);
            a[v] = x;
        } else {
            printf("%lld\n", prefix(tin[v] + size[v] - 1) - prefix(tin[v] - 1));
        }
    }
    return 0;
}
